import java.util.*;

public class MaxFlow {
    static class Edge {
        int to, cap, flow, rev;
        Edge(int t, int c, int f, int r) {
            this.to = t;
            this.cap = c;
            this.flow = f;
            this.rev = r;
        }
    }

    static final int MAXN = 121;
    static List<Edge>[] adj = new ArrayList[MAXN];
    static int[] level = new int[MAXN];
    static int[] ptr = new int[MAXN];
    static int s, t, n;
    static Queue<Integer> q = new LinkedList<>();

    static void addEdge(int v, int u, int cap) {
        adj[v].add(new Edge(u, cap, 0, adj[u].size()));
        adj[u].add(new Edge(v, 0, 0, adj[v].size() - 1));
    }

    static boolean bfs() {
        Arrays.fill(level, -1);
        level[s] = 0;
        q.clear();
        q.offer(s);
        while (!q.isEmpty()) {
            int v = q.poll();
            for (Edge e : adj[v]) {
                if (level[e.to] < 0 && e.cap - e.flow > 0) {
                    level[e.to] = level[v] + 1;
                    q.offer(e.to);
                }
            }
        }
        return level[t] >= 0;
    }

    static int dfs(int v, int f) {
        if (v == t) return f;
        for (; ptr[v] < adj[v].size(); ++ptr[v]) {
            Edge e = adj[v].get(ptr[v]);
            if (level[e.to] == level[v] + 1 && e.cap - e.flow > 0) {
                int pushed = dfs(e.to, Math.min(f, e.cap - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    adj[e.to].get(e.rev).flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        int tbad = sc.nextInt();

        for (int i = 0; i < MAXN; i++) {
            adj[i] = new ArrayList<>();
        }

        char[][] grid = new char[n][n];
        char[][] grid_b = new char[n][n];

        int px = -1, py = -1;

        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < n; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'Z') {
                    px = i;
                    py = j;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < n; j++) {
                grid_b[i][j] = line.charAt(j);
            }
        }

        s = 0;
        t = 2 * n * n + 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int u = i * n + j + 1;
                if (grid[i][j] != '0') {
                    addEdge(s, u, grid[i][j] - '0');
                }
                if (grid_b[i][j] != '0') {
                    addEdge(u + n * n, t, grid_b[i][j] - '0');
                }
            }
        }

        int flow = 0;
        while (bfs()) {
            Arrays.fill(ptr, 0);
            int pushed;
            while ((pushed = dfs(s, Integer.MAX_VALUE)) > 0) {
                flow += pushed;
            }
        }
        System.out.println(flow);
        sc.close();
    }
}

